  const ball = { x: 136, y: 118, r: 7, vx: 0, vy: 300 };

  const hit = sweptHit(prev.x, prev.y, ball, BRICK);
  assert.ok(hit, 'the swept segment should hit the brick');
  assert.equal(hit.ny, -1, 'the hit face should be the top (normal up)');
  assert.equal(hit.nx, 0, 'no sideways face involved');

  applyBounce({ ball }, hit);
  assert.ok(ball.vy < 0, 'vy reverses to travel upward');
  assert.equal(ball.vx, 0, 'horizontal velocity untouched');
  assert.ok(ball.y <= BRICK.y - ball.r, 'ball pushed strictly above the brick');
});

test('brick bounce: side face hit flips vx and pushes the ball left', () => {
  // Ball travels right into the brick's left face.
  const prev = { x: 178, y: 110 };
  const ball = { x: 230, y: 110, r: 7, vx: 300, vy: 0 };

  const hit = sweptHit(prev.x, prev.y, ball, BRICK);
  assert.ok(hit, 'the swept segment should hit the brick');
  assert.equal(hit.nx, -1, 'the hit face should be the left (normal pointing left)');

  applyBounce({ ball }, hit);
  assert.ok(ball.vx < 0, 'vx reverses to travel left');
  assert.ok(ball.x <= BRICK.x - ball.r, 'ball pushed strictly left of the brick');
});

test('brick bounce: ball not on course => no hit', () => {
  const prev = { x: 20, y: 20 };
  const ball = { x: 20, y: 460, r: 7, vx: 0, vy: 300 };
  assert.equal(sweptHit(prev.x, prev.y, ball, BRICK), null);
});

test('brick bounce: tunnelling is caught (fast ball clears the brick in one frame)', () => {
  // At level 6 the ball may jump 35.5 px in a capped frame while a brick is
  // only 34 px across corner-to-corner. The final position is past the brick,
  // so a discrete check would miss it — the sweep must still detect it.
  const prev = { x: 136, y: 90 };   // above the brick
  const ball = { x: 136, y: 190, r: 7, vx: 0, vy: 850 }; // ends up below the brick

  const hit = sweptHit(prev.x, prev.y, ball, BRICK);
  assert.ok(hit, 'a fast ball must not tunnel through the brick');
  assert.equal(hit.ny, -1, 'still recognised as a top-face hit');
  assert.equal(collides(ball, BRICK), false, 'reproduces the discrete miss');

  applyBounce({ ball }, hit);
  assert.ok(ball.vy < 0, 'the ball bounces back upward instead of passing through');
});

test('brick bounce: seam overlap bounces exactly once (no double-flip)', () => {
  // Two bricks side by side with an 8 px gap; the ball (14 px across) straddles
  // the seam. Both are hit in the same pass but the velocity may only be
  // reflected a single time, otherwise vy would flip twice and cancel out.
  const a = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const b = { x: 180, y: 100, w: 72, h: 20, alive: true };
  const prev = { x: 176, y: 92 };
  const ball = { x: 176, y: 118, r: 7, vx: 0, vy: 300 };

  const { hit, bounce } = brickHits(prev.x, prev.y, ball, [a, b]);
  assert.equal(hit.length, 2, 'both bricks in the seam are hit in the same pass');
  assert.ok(bounce, 'a single bounce is resolved');

  applyBounce({ ball }, bounce);
  assert.ok(ball.vy < 0, 'ball bounced up exactly once');
  assert.equal(ball.vx, 0, 'sideways component left untouched');
});

